import torch
from dpms_ant.metrics import intra_lpips
class D:
    def __init__(s): s.using_official=False
    def __call__(s,a,b): return (a-b).reshape(a.shape[0],-1).abs().mean(dim=1)
    def pairwise(s,a,b):
        return torch.stack([s(a[i:i+1].expand(b.shape[0],*a.shape[1:]), b) for i in range(a.shape[0])],0)
